code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color for i in range(r, r + 3) for j in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    claims = {}
    for r, c, color in blocks:
        for j in range(w):
            claims.setdefault((r, j), set()).add(color)
        for i in range(h):
            claims.setdefault((i, c), set()).add(color)
    out = [row[:] for row in grid]
    for (r, c), colors in claims.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
'''
